/* ---------------------------------------------------------------------------
 * The approved logo, cut into its lattice cells, for the collapse.
 *
 * GENERATED from the logo's construction (four pieces on a 7x7 lattice tilted
 * 22°, every corner rounded, no tail links). Do not edit by hand: the
 * outlines are the exact intersections of each piece with each lattice cell,
 * and hand edits would break the seams between neighbours.
 *
 * Coordinates are in the logo's own units. `x`/`y` place a cell's centre on
 * the untilted lattice relative to the body centre (83, 97); `outline` is the
 * cell's share of its piece, relative to that centre, before the tilt. `rank`
 * is the order the collapse reaches the cell in, from the upper-right corner.
 * `tone` picks the piece's ink: 0 solid, 1 base, 2 light. Outlines are stored
 * already simplified (points within .012 of their chord dropped).
 * ------------------------------------------------------------------------- */

export interface CollapseMarkCellData {
  row: number
  col: number
  x: number
  y: number
  rank: number
  outline: readonly (readonly [number, number])[]
}

export interface CollapseMarkPieceData {
  id: string
  tone: 0 | 1 | 2
  cells: readonly CollapseMarkCellData[]
}

/** Lattice pitch in logo units. */
export const COLLAPSE_MARK_PITCH = 14.222222222222221
/** The body's resting tilt, in degrees. */
export const COLLAPSE_MARK_ANGLE = 22

